SELECT DATE_TRUNC('MONTH', hire_date) AS activity_month, COUNT(*) FILTER (WHERE job_title = 'Manager') AS manager_rows, ROUND(SUM(salary) / NULLIF(COUNT(CASE WHEN job_title = 'Engineer' THEN 1 END), 0), 2) AS salary_per_engineer, APPROX_PERCENTILE(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, SIZE(COLLECT_SET(level)) AS num_levels, MAX(salary) AS max_salary FROM employees GROUP BY DATE_TRUNC('MONTH', hire_date);
